// pSFDemo is a registry with project "demo" (Add), and its base.
func pSFDemo(t *testing.T, what string) (*Registry, string) {
	t.Helper()
	base := filepath.Join(t.TempDir(), "state")
	r, err := Open(base)
	if err != nil || r == nil {
